/* machine-generated by m2c: a starting point, not a match */
#ifndef M2C_DEFINES
#define M2C_DEFINES
typedef s32 M2C_UNK;
typedef s8 M2C_UNK8;
typedef s16 M2C_UNK16;
typedef s32 M2C_UNK32;
#define M2C_FIELD(expr, type_ptr, offset) (*(type_ptr)((s8 *)(expr) + (offset)))
#define M2C_BITWISE(type, expr) ((type)(expr))
#define M2C_ERROR(desc) (0)
#define M2C_CARRY 0
#define M2C_OVERFLOW(a) (0)
#endif

extern M2C_UNK gSlotValues;
extern M2C_UNK gSlotValues2;
extern M2C_UNK gSaveSlotValid;
extern M2C_UNK gRumbleFlags;

/* If the slot (0-3) is valid, clears its two value entries and sets its rumble flags to 2. */ void resetControllerSlotState(s32 slotIndex) {
    u32 slot;

    slot = slotIndex & 0xFFFF;
    if ((slot < 4U) && (((u16 *) &gSaveSlotValid)[slot] != 0)) {
        ((s16 *) &gSlotValues)[slot] = 0;
        ((s16 *) &gSlotValues2)[slot] = 0;
        ((s16 *) &gRumbleFlags)[slot] = 2;
    }
}
